// GENERATED by scripts/sync-shared.mjs from src/lib. Do not edit by hand.
// The wire format for editor -> reader publishing.
// Shared by the Supabase edge function, the file-ingest script, the in-app
// importer and the tests. Keep this file free of framework imports.
import { z } from "zod";

export const SCHEMA_VERSION = 1;

const isoDate = z.string().refine((s) => !Number.isNaN(Date.parse(s)), "must be an ISO date");

export const sourceSchema = z.object({
  url: z.string().url(),
  name: z.string().min(1).max(160),
  type: z.enum([
    "primary", "official", "academic", "reporting", "specialist",
    "essay", "archive", "newsletter", "personal", "community",
  ]),
  publishedAt: isoDate.optional(),
  accessedAt: isoDate.optional(),
  note: z.string().max(400).optional(),
});

export const formatEnum = z.enum([
  "update", "explainer", "rabbit_hole", "deep_dive", "series_chapter", "circle",
]);

export const itemSchema = z.object({
  id: z.string().regex(/^[a-z0-9][a-z0-9-]{2,80}$/, "id: lowercase letters, digits and dashes"),
  format: formatEnum,
  headline: z.string().min(8).max(140),
  dek: z.string().max(280).optional(),
  body: z.string().min(80),
  readingMinutes: z.number().int().min(1).max(30).optional(),
  topics: z.array(z.string().min(1).max(60)).min(1).max(8),
  publishedAt: isoDate.optional(),
  eventDate: isoDate.optional(),
  timeliness: z.enum(["current", "evergreen"]),
  significance: z.number().min(0).max(1),
  reason: z.string().max(400).optional(),
  sources: z.array(sourceSchema).max(30),
  caveats: z.array(z.string().max(300)).max(10).optional(),
  seriesId: z.string().optional(),
  chapter: z.number().int().min(1).optional(),
  recap: z.string().max(500).optional(),
  person: z.string().max(120).optional(),
  discoveredVia: z.enum(["web", "inbox", "reddit", "social", "reader-request"]).optional(),
  /** Editor's declared stage. Only "approved" content is eligible for publication. */
  stage: z.enum(["drafted", "validated", "approved"]).default("approved"),
  sample: z.boolean().optional(),
});

export const seriesSchema = z.object({
  id: z.string().regex(/^[a-z0-9][a-z0-9-]{2,80}$/),
  title: z.string().min(4).max(140),
  description: z.string().min(20).max(600),
  subject: z.string().min(2).max(120),
  topics: z.array(z.string()).min(1).max(8),
  motif: z.enum(["orbit", "gear", "wave", "grid", "leaf", "window"]).default("window"),
  researchStatus: z.enum(["pitched", "researching", "ready"]),
  totalChapters: z.number().int().min(3).max(40),
  outline: z.array(z.string().min(3)).min(3).max(40),
  sources: z.array(sourceSchema).max(60),
  reason: z.string().max(400).optional(),
  sample: z.boolean().optional(),
});

export const payloadSchema = z.object({
  schemaVersion: z.literal(SCHEMA_VERSION),
  /** Name of the scheduled task submitting, e.g. "daily-discovery" */
  task: z.string().min(2).max(80),
  /** Idempotency key for the whole submission (re-sending the same run is safe). */
  runId: z.string().min(6).max(120),
  items: z.array(itemSchema).max(60).default([]),
  series: z.array(seriesSchema).max(10).default([]),
  /** Corrections to already-published items */
  corrections: z
    .array(z.object({ itemId: z.string(), note: z.string().min(5).max(500) }))
    .max(30)
    .default([]),
  /** Items the editor wants withdrawn */
  archive: z.array(z.string()).max(60).default([]),
});

export type IngestPayload = z.infer<typeof payloadSchema>;
export type IngestItem = z.infer<typeof itemSchema>;
export type IngestSeries = z.infer<typeof seriesSchema>;

// ---------------------------------------------------------------- Editorial validation

export interface Rejection {
  id: string;
  reasons: string[];
}

/** Words per minute used for reading time everywhere. */
export const WPM = 215;

export function wordCount(body: string): number {
  return body.trim().split(/\s+/).filter(Boolean).length;
}

export function readingMinutes(body: string): number {
  return Math.max(1, Math.round(wordCount(body) / WPM));
}

export function normaliseTitle(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9 ]+/g, " ").replace(/\s+/g, " ").trim();
}

function trigrams(s: string): Set<string> {
  const t = ` ${normaliseTitle(s)} `;
  const out = new Set<string>();
  for (let i = 0; i < t.length - 2; i++) out.add(t.slice(i, i + 3));
  return out;
}

/** Dice coefficient on character trigrams. Cheap and good enough for headlines. */
export function similarity(a: string, b: string): number {
  const A = trigrams(a);
  const B = trigrams(b);
  if (!A.size || !B.size) return 0;
  let hit = 0;
  for (const g of A) if (B.has(g)) hit++;
  return (2 * hit) / (A.size + B.size);
}

export function canonicalUrl(u: string): string {
  try {
    const url = new URL(u);
    url.hash = "";
    for (const k of [...url.searchParams.keys()]) {
      if (k.startsWith("utm_") || k === "ref" || k === "fbclid") url.searchParams.delete(k);
    }
    return (url.hostname.replace(/^www\./, "") + url.pathname.replace(/\/$/, "") + url.search).toLowerCase();
  } catch {
    return u.toLowerCase();
  }
}

export interface ExistingRef {
  id: string;
  headline: string;
  dek?: string;
  topics?: string[];
  sourceUrls: string[];
  seriesId?: string;
  chapter?: number;
}

export interface ValidationContext {
  existing: ExistingRef[];
  /** Series known to the reader (including ones in this payload) */
  knownSeries: Record<string, { totalChapters: number; researchStatus: string }>;
  excludedTopics: string[];
  now?: Date;
}

const DUPLICATE_THRESHOLD = 0.82;

const STOP = new Set(
  "about after again also been being between both could does during each even ever from have here into just like more most much only other over said same some such than that their them then there these they this those through very were what when where which while will with without would your".split(" "),
);

/** Significant words of a headline + subtitle: lowercased, 4+ letters, no filler. */
function keywords(s: string): Set<string> {
  return new Set(
    normaliseTitle(s)
      .split(" ")
      .filter((w) => w.length >= 4 && !STOP.has(w))
      .map((w) => w.replace(/(ing|ed|es|s)$/, "")),
  );
}

/** Overlap (Jaccard) of the significant words in two headline+dek pairs. */
export function storyOverlap(a: string, b: string): number {
  const A = keywords(a);
  const B = keywords(b);
  if (!A.size || !B.size) return 0;
  let hit = 0;
  for (const w of A) if (B.has(w)) hit++;
  return hit / (A.size + B.size - hit);
}

/**
 * "Same story, different sources": wording, topics and sources are compared together.
 * It's a safety net behind the editor's own judgement, tuned to avoid blocking a genuinely
 * different piece on the same broad subject.
 */
export function looksLikeSameStory(
  item: Pick<IngestItem, "headline" | "dek" | "topics" | "sources">,
  e: ExistingRef,
): string | null {
  const overlap = storyOverlap(`${item.headline} ${item.dek ?? ""}`, `${e.headline} ${e.dek ?? ""}`);
  const mine = new Set(item.sources.map((s) => canonicalUrl(s.url)));
  const sharedSource = e.sourceUrls.some((u) => mine.has(canonicalUrl(u)));
  const myTopics = new Set(item.topics.map((t) => t.toLowerCase()));
  const sharedTopics = (e.topics ?? []).filter((t) => myTopics.has(t.toLowerCase())).length;
  if (overlap >= 0.5) return "reads like the same story";
  if (overlap >= 0.28 && sharedTopics >= 2) return "similar wording and the same topics";
  if (overlap >= 0.2 && sharedTopics >= 3) return "similar wording and three or more shared topics";
  if (overlap >= 0.3 && sharedSource) return "shares a source and similar wording";
  return null;
}

/**
 * The automated pass that sits between "drafted" and "published".
 * Returns reasons for rejection; an empty array means the item may publish.
 */
export function validateItem(item: IngestItem, ctx: ValidationContext): string[] {
  const why: string[] = [];

  if (item.stage !== "approved") why.push(`stage is "${item.stage}", not approved`);

  const isSeries = item.format === "series_chapter";
  // Every format needs provenance; circle items must link the original post.
  if (item.sources.length === 0) why.push("no source references");

  if (isSeries) {
    if (!item.seriesId) why.push("series chapter without seriesId");
    if (!item.chapter) why.push("series chapter without chapter number");
    const s = item.seriesId ? ctx.knownSeries[item.seriesId] : undefined;
    if (item.seriesId && !s) why.push(`unknown series "${item.seriesId}"`);
    if (s && item.chapter && item.chapter > s.totalChapters)
      why.push(`chapter ${item.chapter} exceeds series length ${s.totalChapters}`);
    if (s && s.researchStatus !== "ready") why.push("series is not fully researched yet");
    const wc = wordCount(item.body);
    if (wc < 450 || wc > 1100) why.push(`chapter is ${wc} words; expected roughly 600-850`);
  } else if (item.seriesId || item.chapter) {
    why.push("seriesId/chapter only allowed on series_chapter items");
  }

  if (item.format === "circle") {
    if (!item.person) why.push("circle item without a person");
    if (wordCount(item.body) > 160) why.push("circle items must stay brief");
  }

  const wc = wordCount(item.body);
  const limits: Record<string, [number, number]> = {
    update: [90, 650],
    explainer: [250, 1100],
    rabbit_hole: [250, 1300],
    deep_dive: [650, 2200],
    series_chapter: [450, 1100],
    circle: [20, 160],
  };
  const [lo, hi] = limits[item.format];
  if (wc < lo) why.push(`too short for ${item.format} (${wc} words, minimum ${lo})`);
  if (wc > hi) why.push(`too long for ${item.format} (${wc} words, maximum ${hi})`);

  if (item.format === "deep_dive" && !/^~ /m.test(item.body) && !/^## /m.test(item.body))
    why.push("deep dives must separate established fact from analysis (use ## headings or ~ interpretation lines)");

  const excluded = new Set(ctx.excludedTopics.map((t) => t.toLowerCase()));
  for (const t of item.topics) if (excluded.has(t.toLowerCase())) why.push(`topic "${t}" is excluded by the reader`);

  // Guard against injected markup / instructions
  if (/<script|javascript:|onerror=/i.test(item.body)) why.push("body contains script-like content");
  if (/ignore (all |any )?(previous|prior) instructions/i.test(item.body))
    why.push("body contains an instruction-like phrase; needs human review");

  // Duplicates (series chapters are identified by series+chapter instead)
  for (const e of ctx.existing) {
    if (e.id === item.id) continue;
    if (isSeries && e.seriesId === item.seriesId && e.chapter === item.chapter)
      why.push(`duplicate of ${e.id} (same series chapter)`);
    if (!isSeries && similarity(e.headline, item.headline) >= DUPLICATE_THRESHOLD)
      why.push(`near-duplicate headline of ${e.id}`);
    else if (!isSeries && item.format !== "circle") {
      const same = looksLikeSameStory(item, e);
      if (same) why.push(`likely the same story as ${e.id} (${same})`);
    }
    if (!isSeries && item.format !== "circle") {
      const mine = new Set(item.sources.map((s) => canonicalUrl(s.url)));
      const shared = e.sourceUrls.filter((u) => mine.has(canonicalUrl(u)));
      if (mine.size > 0 && shared.length === mine.size && e.sourceUrls.length === mine.size)
        why.push(`same sources as ${e.id}`);
    }
  }
  return why;
}

export interface IngestResult {
  accepted: { id: string; action: "created" | "updated" | "unchanged" }[];
  rejected: Rejection[];
  seriesAccepted: { id: string; action: "created" | "updated" | "unchanged" }[];
  corrected: string[];
  archived: string[];
  warnings: string[];
}
